From 5893e712c08c57aee0bad2c26096b07e093685ca Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:26:19 +0100
Subject: [PATCH] plasmaquick: add a popupAnchor property to PlasmoidItem

Applets had no supported way to pick where their popup opens, so a
launcher couldn't open it in the middle of a dock-like panel. The new
popupAnchor property lets an applet ask for it centered on its panel.

BUG: 518337
---
 src/plasmaquick/appletquickitem.cpp | 15 +++++++++++++++
 src/plasmaquick/appletquickitem.h   | 23 +++++++++++++++++++++++
 src/plasmaquick/appletquickitem_p.h |  4 ++++
 3 files changed, 42 insertions(+)

diff --git a/src/plasmaquick/appletquickitem.cpp b/src/plasmaquick/appletquickitem.cpp
index ab3fa7ebb..0d3b8d357 100644
--- a/src/plasmaquick/appletquickitem.cpp
+++ b/src/plasmaquick/appletquickitem.cpp
@@ -959,6 +959,21 @@ void AppletQuickItem::setBadgeText(const QString &text)
     Q_EMIT badgeTextChanged(text);
 }

+AppletQuickItem::PopupAnchor AppletQuickItem::popupAnchor() const
+{
+    return d->popupAnchor;
+}
+
+void AppletQuickItem::setPopupAnchor(PopupAnchor anchor)
+{
+    if (anchor == d->popupAnchor) {
+        return;
+    }
+
+    d->popupAnchor = anchor;
+    Q_EMIT popupAnchorChanged(anchor);
+}
+
 ////////////Internals

 QQuickItem *AppletQuickItem::compactRepresentationItem()
diff --git a/src/plasmaquick/appletquickitem.h b/src/plasmaquick/appletquickitem.h
index 91c7473af..3096c9ff6 100644
--- a/src/plasmaquick/appletquickitem.h
+++ b/src/plasmaquick/appletquickitem.h
@@ -119,7 +119,25 @@ class PLASMAQUICK_EXPORT AppletQuickItem : public QQuickItem
      */
     Q_PROPERTY(QString badgeText READ badgeText WRITE setBadgeText NOTIFY badgeTextChanged)

+    /*!
+     * Where the popup showing the full representation opens: next to the
+     * applet (\c AppletAnchor), or centered on the panel containing the
+     * applet (\c PanelAnchor). Outside a panel, the popup always opens next
+     * to the applet.
+     *
+     * The default value is \c AppletAnchor.
+     *
+     * @since 6.9
+     */
+    Q_PROPERTY(PopupAnchor popupAnchor READ popupAnchor WRITE setPopupAnchor NOTIFY popupAnchorChanged)
+
 public:
+    enum PopupAnchor {
+        AppletAnchor = 0,
+        PanelAnchor,
+    };
+    Q_ENUM(PopupAnchor)
+
     AppletQuickItem(QQuickItem *parent = nullptr);
     ~AppletQuickItem() override;

@@ -166,6 +184,9 @@ public:
     QString badgeText() const;
     void setBadgeText(const QString &text);

+    PopupAnchor popupAnchor() const;
+    void setPopupAnchor(PopupAnchor anchor);
+
     static bool hasItemForApplet(Plasma::Applet *applet);
     static AppletQuickItem *itemForApplet(Plasma::Applet *applet);

@@ -192,6 +213,8 @@ Q_SIGNALS:

     void badgeTextChanged(QString text);

+    void popupAnchorChanged(PopupAnchor anchor);
+
 protected:
     // Initializations that need to be executed after classBegin()
     virtual void init();
diff --git a/src/plasmaquick/appletquickitem_p.h b/src/plasmaquick/appletquickitem_p.h
index 1cf2e80ad..adf0aaa45 100644
--- a/src/plasmaquick/appletquickitem_p.h
+++ b/src/plasmaquick/appletquickitem_p.h
@@ -14,6 +14,8 @@

 #include <Plasma/Corona>

+#include "appletquickitem.h"
+
 //
 //  W A R N I N G
 //  -------------
@@ -118,6 +120,8 @@ public:

     QString badgeText;

+    AppletQuickItem::PopupAnchor popupAnchor = AppletQuickItem::AppletAnchor;
+
     std::shared_ptr<QQmlEngine> engine;
 };

